// Spec-style helpers expressed as comments for clarity:
//
// is_subrange_at(main, sub, i) is true iff
// 0 <= i <= main.len - sub.len and main[i .. i+sub.len] == sub.
//
// matches_at(main, sub, start) assumes start + sub.len <= main.len and is true iff
// for all j in 0..sub.len: sub[j] == main[start + j].

fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (required by the problem statement):
    // start + sub.len() <= main.len()
    if start + sub.len() > main.len() {
        return false; // defensive; callers should avoid this case
    }

    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    if sub.is_empty() {
        return true;
    }
    if sub.len() > main.len() {
        return false;
    }

    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}

